{"task": "Find event paths that contain a utm_source query parameter", "sql": "SELECT path, status FROM events WHERE regexp_like(path, '[?&]utm_source=')"}
{"task": "Count requests grouped by whether they include a session_id parameter", "sql": "SELECT regexp_like(path, '[?&]session_id=') AS has_session_id, COUNT(*) AS cnt FROM events GROUP BY has_session_id"}
{"task": "List distinct paths with a debug=true flag for potential security review", "sql": "SELECT DISTINCT path FROM events WHERE regexp_like(path, '[?&]debug=true(&|$)')"}
{"task": "Find paths where the page query parameter has a non-numeric value, indicating malformed pagination", "sql": "SELECT path, status FROM events WHERE regexp_like(path, '[?&]page=') AND NOT regexp_like(path, '[?&]page=[0-9]+(&|$)')"}
{"task": "Identify failed requests that included an auth token in the query string, a potential leak", "sql": "SELECT path, status FROM events WHERE status >= 400 AND regexp_like(path, '[?&](token|access_token)=')"}
{"task": "Tag each request path with the query parameters it contains using a CASE expression", "sql": "SELECT path, CASE WHEN regexp_like(path, '[?&]id=[0-9]+') THEN 'has_id' WHEN regexp_like(path, '[?&]q=') THEN 'has_search' ELSE 'other' END AS param_type FROM events"}
{"task": "Find log lines referencing request paths that carry a redirect_uri parameter, useful for spotting open-redirect attempts", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, 'path=\\S*[?&]redirect_uri=')"}
{"task": "Count distinct user_ids hitting paths with an api_key parameter present", "sql": "SELECT COUNT(DISTINCT user_id) AS users_with_api_key FROM events WHERE regexp_like(path, '[?&]api_key=[A-Za-z0-9]+')"}
{"task": "Find paths with a sort parameter restricted to an unexpected or injected value", "sql": "SELECT path FROM events WHERE regexp_like(path, '[?&]sort=') AND NOT regexp_like(path, '[?&]sort=(asc|desc|name|date)(&|$)')"}
{"task": "Join logs and events to find error logs tied to requests that included a limit parameter exceeding typical bounds", "sql": "SELECT e.path, l.ts, l.message FROM events e JOIN logs l ON regexp_like(l.message, e.path) WHERE l.level = 'ERROR' AND regexp_like(e.path, '[?&]limit=[0-9]{4,}(&|$)')"}

